import{z as A,x as B,o as l,c as d,q as r,j as i,D as t,d as n,s,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"梯度下降与学习率","description":"","frontmatter":{"title":"梯度下降与学习率","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sgd-learning-rate.md","filePath":"llm/sgd-learning-rate.md","lastUpdated":1791063341000}'),p={name:"llm/sgd-learning-rate.md"};function h(m,a,D,u,b,g){const E=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=r('<h1 id="梯度下降与学习率" tabindex="-1">梯度下降与学习率 <a class="header-anchor" href="#梯度下降与学习率" aria-label="Permalink to &quot;梯度下降与学习率&quot;">​</a></h1><div class="epigraph"><p>沿损失下降最快的方向走一小步；这一小步有多长，由学习率说了算，不由梯度自己的欧氏长度说了算。</p><footer>—— 据 Cauchy, Méthode générale pour la résolution des systèmes d&#39;équations simultanées, 1847；Goodfellow et al., Deep Learning, 2016 整理</footer></div><p><a href="/llm/clm-as-next-token">下一词分类</a>给出标量损失 \\(L(\\theta)\\)。本课不重写因式分解。缺口是：有了对 \\(\\theta\\) 的导数之后，如何改参数。方法是梯度下降：\\(\\theta\\leftarrow\\theta-\\eta\\nabla_\\theta L\\)。本课只钉住「方向来自梯度、步长来自 \\(\\eta\\)」；小批量噪声、动量、二阶自适应是后课。反向如何算出 \\(\\nabla L\\)，要等到计算图那一单元。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>损失是参数的函数。在当前 \\(\\theta\\)，一阶泰勒说：沿 \\(v\\) 走 \\(\\varepsilon\\)，损失改变约 \\(\\varepsilon\\langle\\nabla L,v\\rangle\\)。要使改变最负，\\(v\\) 应与 \\(-\\nabla L\\) 同向。缺口不是新的损失，而是这条局部规则如何变成一次更新，以及 \\(\\eta\\) 为什么不能从梯度里消掉。</p><p>若令 \\(\\eta\\) 等于 \\(1/\\|\\nabla L\\|\\)，每步都在参数空间走固定欧氏长度，损失的局部曲率一变就会过冲。若令 \\(\\eta\\) 随损失绝对值变，又把损失的任意可加常数引进步长。正确的接口是：\\(\\nabla L\\) 只给方向与相对尺度，\\(\\eta\\) 是独立超参，用来匹配参数的典型量级和损失的局部光滑程度。</p><h3 id="学习率不是「梯度的倒数」" tabindex="-1">学习率不是「梯度的倒数」 <a class="header-anchor" href="#学习率不是「梯度的倒数」" aria-label="Permalink to &quot;学习率不是「梯度的倒数」&quot;">​</a></h3><p>有人把 \\(\\eta\\) 理解成让 \\(\\eta\\|\\nabla L\\|\\) 等于某一个固定的参数扰动。那是在用一阶信息冒充线搜索。真实线搜索要沿该方向试 \\(L\\)，深度学习几乎不做；\\(\\eta\\) 是全局常数或按日程衰减的标量。自适应方法稍后会给每个坐标不同的有效步长，但那是用梯度历史估尺度，仍不是「这一步的梯度取倒数」。把 \\(\\eta\\) 当成梯度归一化，后课 Adam 的 \\(\\hat m/\\sqrt{\\hat v}\\) 会看起来像重复劳动。</p><p><span class="marginnote">全梯度下降用整个训练集的 \\(L\\)。本课先写这一形式，只为把 \\(\\eta\\) 从噪声里分开。下一课才把 \\(\\nabla L\\) 换成小批量估计。实践中几乎从不用全梯度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一次更新 \\(\\theta_{t+1}=\\theta_t-\\eta_t g_t\\)，其中 \\(g_t=\\nabla_\\theta L(\\theta_t)\\)（或下一课的批量估计）。\\(\\eta_t\\) 可以恒定，可以按步数分段衰减，可以按余弦从初值降到末值。选择 \\(\\eta\\) 的量级通常与初始化、层宽、损失平均方式绑定：损失若从「求和」改成「求平均」，梯度缩小 \\(B\\) 倍，\\(\\eta\\) 往往要放大，否则名义上的同一数字其实不是同一有效步长。</p><p><span class="marginnote">梯度下降的经典类比：蒙着眼在山上找最低谷，每一步用脚感受最陡的下坡方向（梯度），步幅由学习率定。步幅太大，容易一步跨过谷底荡到对面山坡；太小，天黑了还没走到谷底。</span></p><p><span class="marginnote">数字实例：把 batch 损失从「求和」改成「求平均」，每个梯度分量都除以 \\(B=256\\)。若 \\(\\eta\\) 不相应放大 256 倍，等效步长只剩原来的 \\(1/256\\)——表面上还是同一个学习率数字，训练实际突然慢了两百多倍。</span></p><p>停步条件不是本课的重点。本课只需承认：固定 \\(\\eta\\) 时，靠近极小点若曲率很大，会在谷底振荡；曲率很小，则走得极慢。这是一阶方法的几何，不是实现 bug。</p>',14)),(l(),i(o,null,{default:t(()=>[s(E,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E6%A0%87%E9%87%8F%E6%8D%9F%E5%A4%B1%20L%22%5D%20--%3E%20G%5B%22%E6%A2%AF%E5%BA%A6%20g%22%5D%0A%20%20ETA%5B%22%E5%AD%A6%E4%B9%A0%E7%8E%87%20eta%22%5D%20--%3E%20UPD%5B%22theta%20%E5%87%8F%E5%8E%BB%20eta%20%E4%B9%98%20g%22%5D%0A%20%20G%20--%3E%20UPD%0A%20%20UPD%20--%3E%20TH%5B%22%E6%96%B0%E7%9A%84%E5%8F%82%E6%95%B0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"\\(\\eta\\) 把参数空间的欧氏度量强加给损失的几何。损失在不同层、不同矩阵上的尺度可以差几个数量级，同一 \\(\\eta\\) 对有的坐标过大、对有的过小。这正是后课自适应方法要补的缺口。本课先把问题暴露出来：不是「先把网络训好再谈优化」，而是没有 \\(\\eta\\) 就没有训练。",-1)),a[5]||(a[5]=e("p",null,"梯度下降保证的是：在 \\(\\eta\\) 足够小、 \\(L\\) 足够光滑时，一步之后 \\(L\\) 不会上升。足够小取决于 Lipschitz 常数一类量，实践中靠试。过大的 \\(\\eta\\) 让损失发散或长期震荡；过小的 \\(\\eta\\) 让人误以为模型没有容量。调 \\(\\eta\\) 是在调这条一阶程序，不是在调词表。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"初学者容易把「损失不降」归因于模型容量不够或数据不行；更常见的罪魁是 \\(\\eta\\) 过小或日程不当。先扫学习率（例如按 10 倍一档，从 \\(10^{-5}\\) 扫到 \\(10^{-1}\\)），再谈别的——这是调参的第一反射。")],-1)),a[7]||(a[7]=e("p",null,"三种 \\(\\eta\\) 量级下，同一条谷底路上的命运分岔：",-1)),(l(),i(o,null,{default:t(()=>[s(E,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E5%AD%A6%E4%B9%A0%E7%8E%87%20eta%20%E7%9A%84%E9%87%8F%E7%BA%A7%22%5D%20--%3E%20BIG%5B%22%E8%BF%87%E5%A4%A7%EF%BC%9A%E4%B8%80%E6%AD%A5%E8%B7%A8%E8%BF%87%E8%B0%B7%E5%BA%95%22%5D%0A%20%20BIG%20--%3E%20B1%5B%22%E6%8D%9F%E5%A4%B1%E4%B8%8A%E4%B8%8B%E9%9C%87%E8%8D%A1%E7%94%9A%E8%87%B3%E5%8F%91%E6%95%A3%22%5D%0A%20%20E%20--%3E%20SMALL%5B%22%E8%BF%87%E5%B0%8F%EF%BC%9A%E6%AD%A5%E5%AD%90%E7%BB%86%E7%A2%8E%22%5D%0A%20%20SMALL%20--%3E%20S1%5B%22%E6%8D%9F%E5%A4%B1%E4%B8%8B%E9%99%8D%E6%9E%81%E6%85%A2%EF%BC%8C%E8%AF%AF%E4%BB%A5%E4%B8%BA%E8%AE%AD%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20E%20--%3E%20FIT%5B%22%E5%90%88%E9%80%82%EF%BC%9A%E7%A8%B3%E6%AD%A5%E4%B8%8B%E9%99%8D%22%5D%0A%20%20FIT%20--%3E%20F1%5B%22%E9%9D%A0%E8%BF%91%E8%B0%B7%E5%BA%95%E4%B9%9F%E4%B8%8D%E9%A3%9E%E5%87%BA%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不计算梯度，只使用它。不讲牛顿法、不讲自然梯度。下一课<a href="/llm/minibatch-noise">小批量噪声</a>把 \\(g\\) 换成随机估计，并解释噪声为何既妨碍又有用。后课默认：参数更新是减 \\(\\eta\\) 乘梯度；改变损失的平均方式必须同时声明对 \\(\\eta\\) 的影响。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一阶更新沿 \\(-\\nabla L\\)，步长由独立的学习率 \\(\\eta\\) 给定。</li><li>\\(\\eta\\) 不是梯度的归一化常数；损失从求和改成平均会改变有效步长。</li><li>过大则震荡或发散，过小则看似训不动。</li><li>全梯度只是记号；实现几乎总是后课的小批量。</li><li>出处：Cauchy, 1847；Goodfellow et al., Deep Learning, 2016。</li></ul>',4))])}const L=A(p,[["render",h]]);export{f as __pageData,L as default};
